// SPDX-License-Identifier: MPL-2.0
// Oracle hook (docs/FIXTURES.md): d2cli PNG rendering of the positioned-tooltip
// target shapes regenerated by recipe render-positioned-tooltip
// (crates/d2-rs-render/tests/fixtures/positioned-tooltip-source-v090.json, read from
// $D2RS_FIXTURES_DIR). Writes every row's admission error, and for the
// successful unicode-text ("-text2-") rows the decoded PNG dimensions and the
// sha256 of its RGB bytes. Harvested from the v0.9.0-era probe
// d2cli/positioned_tooltip_png_probe_test.go; retargeted to the manifest pin.
// Inert unless run by scripts/regen-fixtures.py.
package d2cli

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"image"
	"image/png"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/d2lang/d2/d2renderers/d2fonts"
	"github.com/d2lang/d2/d2renderers/d2svg"
	"github.com/d2lang/d2/d2target"
)

func TestD2RSPositionedTooltipPNG(t *testing.T) {
	if os.Getenv("D2RS_RECIPE_OUTPUT") == "" {
		t.Skip("run via scripts/regen-fixtures.py")
	}
	outputs := filepath.SplitList(os.Getenv("D2RS_RECIPE_OUTPUTS"))
	b, err := os.ReadFile(filepath.Join(os.Getenv("D2RS_FIXTURES_DIR"), "crates/d2-rs-render/tests/fixtures/positioned-tooltip-source-v090.json"))
	if err != nil {
		t.Fatal(err)
	}
	var rows []map[string]json.RawMessage
	if err := json.Unmarshal(b, &rows); err != nil {
		t.Fatal(err)
	}
	font := d2fonts.SourceSansPro
	mono := d2fonts.SourceCodePro
	encoder := &rasterPNGEncoder{}
	defer encoder.close()
	type admission struct {
		Name  string `json:"name"`
		Error string `json:"error"`
	}
	type unicode struct {
		Error      string `json:"error"`
		File       string `json:"file"`
		Name       string `json:"name"`
		Dimensions [2]int `json:"dimensions"`
		RGB        string `json:"rgb_sha256"`
	}
	admissions := []admission{}
	pixels := []unicode{}
	for _, row := range rows {
		var name string
		var shape d2target.Shape
		if err := json.Unmarshal(row["name"], &name); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(row["shape"], &shape); err != nil {
			t.Fatal(err)
		}
		diagram := &d2target.Diagram{Shapes: []d2target.Shape{shape}, FontFamily: &font, MonoFontFamily: &mono}
		encoded, err := renderPNGWithEncoder(context.Background(), "", false, diagram, d2svg.RenderOpts{}, encoder)
		a := admission{Name: name}
		if err != nil {
			a.Error = err.Error()
		}
		admissions = append(admissions, a)
		if err != nil || !strings.Contains(name, "-text2-") {
			continue
		}
		img, err := png.Decode(bytes.NewReader(encoded))
		if err != nil {
			t.Fatal(err)
		}
		bounds := img.Bounds()
		nrgba := image.NewNRGBA(bounds)
		for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
			for x := bounds.Min.X; x < bounds.Max.X; x++ {
				nrgba.Set(x, y, img.At(x, y))
			}
		}
		rgb := make([]byte, 0, bounds.Dx()*bounds.Dy()*3)
		for i := 0; i < len(nrgba.Pix); i += 4 {
			rgb = append(rgb, nrgba.Pix[i], nrgba.Pix[i+1], nrgba.Pix[i+2])
		}
		digest := sha256.Sum256(rgb)
		pixels = append(pixels, unicode{File: name + ".png", Name: name, Dimensions: [2]int{bounds.Dx(), bounds.Dy()}, RGB: hex.EncodeToString(digest[:])})
	}
	for i, value := range []any{admissions, pixels} {
		data, err := json.MarshalIndent(value, "", "  ")
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(outputs[i], append(data, '\n'), 0o644); err != nil {
			t.Fatal(err)
		}
	}
}
